// Python repr()/print() emulation for JS values (zero dependencies, ESM).

function reprString(s) {
  // Always escape backslash and control chars first.
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  let quote = "'";
  if (hasSingle && !hasDouble) {
    quote = '"';
  }
  let out = '';
  for (const ch of s) {
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === "'" && quote === "'") {
      out += "\\'";
    } else {
      out += ch;
    }
  }
  return quote + out + quote;
}

export function pyRepr(value) {
  if (value === null || value === undefined) {
    return 'None';
  }
  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }
  if (typeof value === 'number') {
    if (Number.isInteger(value)) {
      return String(value);
    }
    return String(value);
  }
  if (typeof value === 'string') {
    return reprString(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (typeof value === 'object') {
    const items = Object.keys(value).map(
      (k) => reprString(k) + ': ' + pyRepr(value[k])
    );
    return '{' + items.join(', ') + '}';
  }
  // Fallback for anything unexpected.
  return String(value);
}

export function pyPrint(value) {
  if (typeof value === 'string') {
    return value;
  }
  return pyRepr(value);
}

