// extract(obj, path) — parse a deepdiff-style path like
// root['users'][0]['name'] and return the value at that location.

const SEGMENT_RE = /\['((?:[^'\\]|\\.)*)'\]|\[(-?\d+)\]/g;

function parseSegments(path) {
  if (typeof path !== 'string' || !path.startsWith('root')) {
    throw new Error(`invalid path: ${path}`);
  }
  const segments = [];
  const rest = path.slice(4); // after 'root'
  let pos = 0;
  SEGMENT_RE.lastIndex = 0;
  let m;
  while ((m = SEGMENT_RE.exec(rest)) !== null) {
    if (m.index !== pos) {
      throw new Error(`invalid path: ${path}`);
    }
    pos = m.index + m[0].length;
    if (m[1] !== undefined) {
      segments.push(m[1].replace(/\\'/g, "'").replace(/\\\\/g, '\\'));
    } else {
      segments.push(Number(m[2]));
    }
  }
  if (pos !== rest.length) {
    throw new Error(`invalid path: ${path}`);
  }
  return segments;
}

export function extract(obj, path) {
  let cur = obj;
  for (const seg of parseSegments(path)) {
    if (cur === null || cur === undefined) {
      throw new Error(`cannot extract ${path}: hit undefined`);
    }
    cur = cur[seg];
  }
  return cur;
}

export default extract;

