// Minimal argparse clone for: usage: <prog> [-h] --a A --b B
import { basename } from 'node:path';

function prog() {
  return basename(process.argv[1] || 'test11.mjs');
}

function fail(message) {
  const p = prog();
  process.stderr.write(`usage: ${p} [-h] --a A --b B\n`);
  process.stderr.write(`${p}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  const p = prog();
  process.stdout.write(`usage: ${p} [-h] --a A --b B\n`);
  process.stdout.write('\n');
  process.stdout.write('options:\n');
  process.stdout.write('  -h, --help  show this help message and exit\n');
  process.stdout.write('  --a A\n');
  process.stdout.write('  --b B\n');
  process.exit(0);
}

function parseIntStrict(raw) {
  const s = String(raw).trim();
  if (!/^[+-]?\d+$/.test(s)) {
    fail(`argument --b: invalid int value: '${raw}'`);
  }
  return parseInt(s, 10);
}

export function parseArgs(argv) {
  let a;
  let b;
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (tok === '-h' || tok === '--help') {
      printHelp();
    } else if (tok === '--a') {
      if (i + 1 >= argv.length) fail('argument --a: expected one argument');
      a = argv[++i];
    } else if (tok.startsWith('--a=')) {
      a = tok.slice(4);
    } else if (tok === '--b') {
      if (i + 1 >= argv.length) fail('argument --b: expected one argument');
      b = argv[++i];
    } else if (tok.startsWith('--b=')) {
      b = tok.slice(4);
    } else {
      extras.push(tok);
    }
  }

  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }

  const missing = [];
  if (a === undefined) missing.push('--a');
  if (b === undefined) missing.push('--b');
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  return { a, b: parseIntStrict(b) };
}

export default parseArgs;

